import type { VNode, VNodeChild } from '../vnode'
import { ReactiveSource, shallowReadArray, toReactive } from '@vue/reactivity'
import { isObject } from '@vue/shared'
import { warn } from '../warning'

class ListRenderer {
  cached: VNode[] | undefined
  cacheStore: any[] | undefined
  cacheIndex: number | undefined

  constructor(cache?: any[], index?: number) {
    this.cacheStore = cache
    this.cacheIndex = index
    this.cached = (cache && cache[index!]) as VNode[] | undefined
  }

  renderSource(
    profile: ReactiveSource,
    renderItem: (...args: any[]) => VNodeChild,
  ): VNodeChild[] {
    let ret: VNodeChild[]
    const cached = this.cached
    let source = profile.value
    const sourceIsArray = profile.isArray

    if (sourceIsArray || profile.isString) {
      const sourceIsReactiveArray =
        sourceIsArray &&
        (profile.isReadonly ? profile.rawIsReactive : profile.isReactive)
      if (sourceIsReactiveArray) {
        source = shallowReadArray(profile.raw || source)
      }
      ret = new Array(source.length)
      for (let i = 0, l = source.length; i < l; i++) {
        ret[i] = renderItem(
          sourceIsReactiveArray ? toReactive(source[i]) : source[i],
          i,
          undefined,
          cached && cached[i],
        )
      }
    } else if (typeof source === 'number') {
      if (__DEV__ && !Number.isInteger(source)) {
        warn(`The v-for range expect an integer value but got ${source}.`)
      }
      ret = new Array(source)
      for (let i = 0; i < source; i++) {
        ret[i] = renderItem(i + 1, i, undefined, cached && cached[i])
      }
    } else if (isObject(source)) {
      if (source[Symbol.iterator as any]) {
        ret = Array.from(source as Iterable<any>, (item, i) =>
          renderItem(item, i, undefined, cached && cached[i]),
        )
      } else {
        const keys = Object.keys(source)
        ret = new Array(keys.length)
        for (let i = 0, l = keys.length; i < l; i++) {
          const key = keys[i]
          ret[i] = renderItem(source[key], key, i, cached && cached[i])
        }
      }
    } else {
      ret = []
    }

    if (this.cacheStore) {
      this.cacheStore[this.cacheIndex!] = ret
    }
    return ret
  }
}

/**
 * v-for string
 * @private
 */
export function renderList(
  source: string,
  renderItem: (value: string, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for number
 */
export function renderList(
  source: number,
  renderItem: (value: number, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for array
 */
export function renderList<T>(
  source: T[],
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for iterable
 */
export function renderList<T>(
  source: Iterable<T>,
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for object
 */
export function renderList<T>(
  source: T,
  renderItem: <K extends keyof T>(
    value: T[K],
    key: string,
    index: number,
  ) => VNodeChild,
): VNodeChild[]

/**
 * Actual implementation
 */
export function renderList(
  source: any,
  renderItem: (...args: any[]) => VNodeChild,
  cache?: any[],
  index?: number,
): VNodeChild[] {
  return new ListRenderer(cache, index).renderSource(
    new ReactiveSource(source),
    renderItem,
  )
}

